T('Tireur en surplomb : un tireur d’élite prend un poste en hauteur à la mise en garde',()=>{if(!UPH.length)return'';const q=sqTestSq(3),al=q.m.filter(b=>!b.dead);const sn=al[al.length-1];const tv=[sn.ty,sn.T];sn.ty=2;sn.T=BT[2];let ok=0;try{const hs=UPH.slice(0,UPH.length);for(let k=0;k<3&&!ok;k++)for(const h of hs){sn.lvl=0;sn.route=null;sn.path=null;sn.g.position.set(h.cx+rnd(-8,8),GH(h.cx,h.cz),h.cz+rnd(-8,8));sn.lk.x=h.cx+rnd(25,40);sn.lk.z=h.cz;P.x=sn.lk.x;P.z=sn.lk.z;if(sqOverwatch(q,[sn],{},[0,0])>0){ok=1;break}}}finally{sn.ty=tv[0];sn.T=tv[1];sn.route=null;sn.lvl=0;sn.path=null}return ok?'':'aucun poste en hauteur atteint'});
